import {completed} from './engine.js';
import {explainTask} from './planner.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function pretty(day,opts={weekday:'short',month:'short',day:'numeric'}){return new Intl.DateTimeFormat('en-GB',{timeZone:'UTC',...opts}).format(new Date(day+'T12:00:00Z'));}
export {renderCalendarView} from './calendar-view.js';
export function renderCurriculumView(s,{search='',filter='active',semester='',resource='',catalog}){
 const done=completed(s),tasks=s.tasks.filter(t=>(filter==='suspended'?t.archived:!t.archived)&&(filter==='suspended'||filter==='all'||filter==='active'&&t.status==='active'&&!done.has(t.id)||filter==='completed'&&done.has(t.id)||filter==='draft'&&t.status==='draft')&&(!semester||t.semester===Number(semester))&&(!resource||t.resourceId===resource)&&`${t.title} ${t.resource} ${t.heading}`.toLowerCase().includes(search.toLowerCase()));
 const groups=s.resources.filter(r=>tasks.some(t=>t.resourceId===r.id)).sort((a,b)=>(a.order??999)-(b.order??999)||a.name.localeCompare(b.name));
 return `<div class="page-heading compact"><div><p class="eyebrow">YOUR LIVING CURRICULUM</p><h1>A steady <em>direction.</em></h1><p class="subtitle">Resources → source units → authored learning actions.</p></div><div class="button-row"><button class="secondary" data-action="catalog">Review catalog import</button><button class="primary" data-action="new">+ Add ENSAM course / task</button></div></div><div class="tabs semester-tabs" role="tablist" aria-label="Curriculum semester"><button role="tab" data-semester-select="" aria-selected="${!semester}" tabindex="${!semester?0:-1}" class="${!semester?'selected':''}">All</button>${s.semesters.map(sem=>`<button role="tab" data-semester-select="${sem.id}" aria-selected="${String(sem.id)===semester}" tabindex="${String(sem.id)===semester?0:-1}" class="${String(sem.id)===semester?'selected':''}">S${sem.id}</button>`).join('')}</div><details class="semester-overview"><summary>Six-semester overview and date assumptions</summary><div class="phase-strip">${s.semesters.map(sem=>`<div><small>${sem.confidence==='planning_assumption'?'TENTATIVE':'2026–27 PLANNING ENVELOPE'}</small>S${sem.id} · ${esc(sem.title)}<button class="text-button" data-semester-edit="${sem.id}">Edit dates</button></div>`).join('')}</div></details><p class="muted small">${catalog.units.length} public catalog units available for review. ${s.archiveRegistry.length} private archive references contain no filenames or documents. Historical materials require current teacher confirmation. Only reviewed + activated tasks are actionable.</p><div class="library-toolbar"><div class="tabs">${['active','draft','completed','suspended','all'].map(x=>`<button data-filter="${x}" class="${filter===x?'selected':''}">${x==='draft'?'Research':x}</button>`).join('')}</div><input id="search" aria-label="Search curriculum" placeholder="Search topics or resources…" value="${esc(search)}"></div><div class="form-columns"><label>Semester<select id="semester-filter"><option value="">All semesters</option>${s.semesters.map(x=>`<option value="${x.id}" ${String(x.id)===semester?'selected':''}>S${x.id} · ${esc(x.title)}</option>`).join('')}</select></label><label>Resource<select id="resource-filter"><option value="">All resources</option>${s.resources.map(r=>`<option value="${esc(r.id)}" ${r.id===resource?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></div>${groups.map(r=>`<details class="resource-group"><summary>${esc(r.name)} <small>${esc(r.edition||'Edition unconfirmed')} · ${r.enabled?'enabled':'suspended'} · ${s.tasks.filter(t=>t.resourceId===r.id&&done.has(t.id)).length}/${s.tasks.filter(t=>t.resourceId===r.id).length} explicitly completed</small></summary><button class="text-button" data-resource-edit="${esc(r.id)}">Edit resource</button> · <button class="text-button" data-resource-toggle="${esc(r.id)}">${r.enabled?'Suspend resource':'Enable resource'}</button>${tasks.filter(t=>t.resourceId===r.id).sort((a,b)=>(a.order??999)-(b.order??999)||a.id.localeCompare(b.id)).map(t=>{const u=s.units.find(u=>u.id===t.unitId);return `<article class="task-row"><span class="task-bullet ${done.has(t.id)?'done':''}">${done.has(t.id)?'✓':'○'}</span><div><span class="tiny-label">S${t.semester} · ${esc(t.priority)} · ${done.has(t.id)?'COMPLETED':t.status==='active'?'ACTIVE':'RESEARCH'} · ${esc(u?.confidence||'USER AUTHORED')}</span><h3>${esc(t.section+' '+t.heading)}</h3><p>${esc(t.action)}</p><small>${t.prerequisites.length} prerequisites · ${t.reviewed?'reviewed':'unreviewed'}</small></div><span class="row-time">${t.minutes} min<br><small>estimate</small></span><button class="text-button" data-edit="${esc(t.id)}">Review →</button></article>`;}).join('')}</details>`).join('')||'<p class="empty">No matching tasks. Review the catalog to stage new units.</p>'}`;
}
export function renderPlanningSettings(s){return `<section class="panel planning-settings"><h2>Weekly slots & semester roles</h2><p class="muted">Fixed roles follow each semester’s resource allocation. Wednesday stays ENSAM-only. Flexible slots allow activated independent subjects; protected days still win.</p>${s.calendarSlots.map(slot=>`<div class="slot-editor"><b>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][slot.day]}</b><label>Independent min<input name="slot-${slot.day}" type="number" min="0" max="${[0,3,5].includes(slot.day)?0:slot.day===6?180:90}" ${[0,3,5].includes(slot.day)?'readonly':''} value="${slot.minutes}"></label><label class="checkbox"><input name="fixed-${slot.day}" type="checkbox" ${slot.fixed?'checked':''}> Fixed role</label></div>`).join('')}<label>Preferred subjects <select name="preferredResources" multiple size="4">${s.resources.map(r=>`<option value="${esc(r.id)}" ${s.settings.preferredResources.includes(r.id)?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>Exam-prep lead days<input type="number" name="examPrepLeadDays" min="0" max="90" value="${s.settings.examPrepLeadDays}"></label><label class="checkbox"><input type="checkbox" name="pfeMode" ${s.settings.pfeMode?'checked':''}> PFE priority (pause independent study)</label><label>Recovery dates, comma-separated<input name="recoveryDays" value="${esc(s.settings.recoveryDays.join(', '))}" placeholder="2026-11-20, 2026-11-23"></label><label class="checkbox"><input name="crossDayRescue" type="checkbox" ${s.settings.crossDayRescue?'checked':''}> Allow small partials in unused slack (never replace a home-track block)</label><label>Small partial threshold (minutes)<input name="smallResidualMinutes" type="number" min="1" max="50" value="${s.settings.smallResidualMinutes??30}"></label><p class="muted">Actual discretionary time shared by all study, before campus reservations:</p><div class="form-columns">${Array.from({length:7},(_,day)=>`<label>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][day]} available min<input name="available-${day}" type="number" min="0" max="1440" value="${s.settings.discretionaryMinutes?.[day]??(day===6?s.settings.saturdayMinutes:s.settings.dailyMinutes)}"></label>`).join('')}</div><p class="muted">Campus timetable: reserve unavailable minutes from each day’s study capacity.</p><div class="form-columns">${Array.from({length:7},(_,day)=>`<label>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][day]} unavailable min<input name="campus-${day}" type="number" min="0" max="1440" value="${s.settings.campusTimetable.find(c=>c.day===day)?.minutes||0}"></label>`).join('')}</div><button class="primary" type="submit">Save all preferences</button></section>`;}
export function taskProvenance(s,t,day){const e=explainTask(s,t,day);return `<div class="provenance"><p><b>${esc(e.confidence)}</b> · ${esc(e.source)}</p><p>Source-defined heading: ${esc(e.heading)}<br>Edition: ${esc(e.edition)}</p><p>AUTHORED action: ${esc(e.objective)}<br>ESTIMATED effort: ${t.minutes} min</p><p>Why today: ${esc(e.why)}</p><p>Completion evidence: ${esc(e.evidence)}</p><p>Prerequisites: ${e.prerequisites.map(p=>`${p.satisfied?'✓':'○'} ${esc(p.id)} · ${esc(p.heading)}`).join('; ')||'None'}</p>${e.attachment?`<p>Private local document: ${esc(e.attachment)}</p>`:''}</div>`;}
export function renderWindowEditor(t){return `<form id="event-form"><p class="eyebrow">ACADEMIC WINDOW</p><h2>${esc(t.title)}</h2><label>Window name<input name="title" value="${esc(t.title)}" required></label><label>Protection type<select name="kind">${['exam_window','exam_prep','conditional_resit','recovery','no_work','holiday','teaching','readiness'].map(k=>`<option value="${k}" ${t.kind===k?'selected':''}>${esc(k.replaceAll('_',' '))}</option>`).join('')}</select></label><p class="small muted">${esc(t.provenance||'A calendar window is separate from your personal exam timetable. Enter only dates you want to use.')}</p><label>Start date<input name="start" type="date" value="${t.start_date}" required></label><label>End date (inclusive)<input name="end" type="date" value="${t.end_date_inclusive}" required></label><label class="checkbox"><input type="checkbox" name="active" ${t.active?'checked':''}> Enable this window</label><div class="dialog-actions"><button type="button" data-close class="text-button">Cancel</button><button class="primary">Save dates</button></div></form>`;}
